#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using i128 = __int128_t;

void print(i128 value) {
    if (value == 0) {
        cout << 0;
        return;
    }
    if (value < 0) {
        cout << '-';
        value = -value;
    }
    string result;
    while (value > 0) {
        result.push_back(char('0' + value % 10));
        value /= 10;
    }
    reverse(result.begin(), result.end());
    cout << result;
}

int main() {
    ll n, x, y;
    cin >> n >> x >> y;

    i128 req = ((i128)n * y + 99) / 100;
    print(req <= x ? 0 : req - x);

    return 0;
}

